function text(id,value){if(id==='status'&&!/^(Correct!|Try again!|Catch |Move |Trap!|Choose |Out of lives)/.test(value))value='';$(id).textContent=value;}
function ensureAudio(){if(muted)return false;try{audioContext ||= new (window.AudioContext||window.webkitAudioContext)();if(audioContext.state==='suspended')audioContext.resume().catch(()=>{});return true;}catch{muted=true;return false;}}
function note(freq=440,duration=.12,type='triangle',gain=.045,delay=0,end=freq){if(!ensureAudio())return;try{const now=audioContext.currentTime+delay,o=audioContext.createOscillator(),g=audioContext.createGain();o.type=type;o.frequency.setValueAtTime(freq,now);o.frequency.exponentialRampToValueAtTime(Math.max(20,end),now+duration);g.gain.setValueAtTime(.001,now);g.gain.linearRampToValueAtTime(gain,now+.01);g.gain.exponentialRampToValueAtTime(.001,now+duration);o.connect(g).connect(audioContext.destination);audioNodes.add(o);o.onended=()=>{audioNodes.delete(o);o.disconnect();g.disconnect();};o.start(now);o.stop(now+duration+.01);}catch{}}
function tone(freq=440,duration=.12){note(freq,duration);}
function sfx(name){
 const tunes={start:[330,440,660],reveal:[440,660],correct:[523,659,784,1047],catch:[784,1047,1319],relic:[392,523,659,784],insert:[392,587,784],treasure:[523,659,784,1047,1319,1568]};
 if(tunes[name]){tunes[name].forEach((f,i)=>note(f,.17,'triangle',.045,i*.085));return;}
 if(name==='rail'){note(110,.035,'square',.012);note(165,.035,'triangle',.02,.06);}
 if(name==='trap'){note(320,.5,'sawtooth',.035,0,65);note(65,.26,'triangle',.07,.1,30);}
 if(name==='bounce'){note(120,.35,'triangle',.045,0,700);}
 if(name==='throw'){note(240,.24,'sine',.045,0,1100);}
 if(name==='hit'){note(100,.24,'sawtooth',.05,0,35);note(880,.26,'triangle',.04,.03,300);}
 if(name==='reject'){note(740,.14,'square',.025,0,200);}
 if(name==='death'){[160,120,80].forEach((f,i)=>note(f,.35,'sawtooth',.035,i*.17,35));note(880,.8,'sine',.04,.5,1760);}
 if(name==='unlock'){note(70,.8,'triangle',.065,0,250);[440,554,659].forEach((f,i)=>note(f,.55,'sine',.025,.2+i*.06));}
 if(name==='jump')note(180,.14,'triangle',.035,0,440);
}
function stopAudio(){for(const o of audioNodes){try{o.stop();}catch{}}audioNodes.clear();}
function modal(html,buttons,onClose){keys.clear();resumePhase=phase;phase='modal';$('dialog-content').innerHTML=html+'<div class="dialog-actions"></div>';let area=$('dialog-content').querySelector('.dialog-actions');buttons.forEach(([label,fn,primary])=>{let b=document.createElement('button');b.textContent=label;b.className=primary?'primary':'secondary';b.onclick=()=>{$('dialog').close();phase=resumePhase;resumePhase=null;dialogCallback=null;if(!muted)ensureAudio();fn?.();};area.append(b);});dialogCallback=onClose||buttons[0]?.[1];$('dialog').showModal();}
$('dialog').addEventListener('cancel',e=>{e.preventDefault();$('dialog').close();phase=resumePhase;resumePhase=null;let fn=dialogCallback;dialogCallback=null;if(!muted)ensureAudio();fn?.();});
function shuffleQuestion(source,rng=Math.random){const choices=source.a.map((answer,i)=>({answer,correct:i===source.correct}));for(let i=choices.length-1;i>0;i--){const j=Math.floor(rng()*(i+1));[choices[i],choices[j]]=[choices[j],choices[i]];}return {...source,a:choices.map(c=>c.answer),correct:choices.findIndex(c=>c.correct)};}
function current(){return roundQuestion||levels[level].questions[round];}
function burst(x,y,color){if(reduced)return;for(let i=0;i<24;i++)particles.push({x,y,vx:(Math.random()-.5)*230,vy:-Math.random()*190-30,life:.8+Math.random()*.5,color});if(particles.length>100)particles.splice(0,particles.length-100);}
function updateProgress(){$('lives').innerHTML=Array.from({length:5},(_,i)=>'<span class="'+(i<lives?'heart-full':'heart-empty')+'">♥</span>').join('');$('lives').setAttribute('aria-label',lives+' of 5 lives remaining');$('relics').innerHTML='◇ <span>'+relics+' / 3</span>';$('relics').setAttribute('aria-label',relics+' of 3 relics collected');}
function startGame(){goldenFlower=false;secretScene=null;codeTrail=[];$('stage').classList.remove('secret-active');$('secret-badge').hidden=true;lives=5;roundQuestion=null;stopAudio();ensureAudio();cinematic=null;bossGone=false;shake=0;rings=[];$('cinema-caption').hidden=true;$('stage').classList.remove('is-cinematic');sfx('start');level=0;round=0;relics=0;mistakes=0;firstTry=0;playSeconds=0;startedAt=Date.now();$('intro').hidden=true;$('question-panel').hidden=false;introduce();}
