function revealQuestion(){sfx('reveal');phase='reveal';revealElapsed=0;keys.clear();$('question-panel').classList.add('revealing');document.querySelector('.reveal-bar i').style.width='0%';$('answers').hidden=true;$('action-row').hidden=true;lockAnswers(true);}
function finishReveal(){keys.clear();phase=level===1?'read':'choose';$('question-panel').classList.remove('revealing');$('answers').hidden=false;$('action-row').hidden=false;lockAnswers(false);if(level===1){text('challenge-label','CHOOSE & CATCH');text('status','Choose an answer, then catch its NPC.');}}
function setupRound(){roundQuestion=shuffleQuestion(levels[level].questions[round]);cinematic=null;bossGone=false;shake=0;rings=[];catchCooldown=0;$('cinema-caption').hidden=true;$('chase-controls').hidden=true;$('stage').classList.remove('is-chase');phase=level===1?'read':'choose';selected=-1;held=-1;eliminated.clear();autoTarget=-1;projectile=null;ride=null;hadMistake=false;particles=[];camera=0;player={x:120,y:ground,vx:0,vy:0,face:1};targets=[0,1,2].map(i=>({x:440+i*240,base:440+i*240,y:ground,dir:i%2?1:-1}));
  text('eyebrow','CHAPTER 0'+(level+1)+' / '+levels[level].region);text('title',levels[level].name);text('session','Take your time. Keep exploring.');text('place-label',levels[level].region);text('scene-caption',levels[level].region+' / RELIC '+(level+1));text('challenge-label',levels[level].mode);text('question-count',(round+1)+' / 3');text('question',current().q);
  text('instruction',level===0?'Choose a track with 1 / 2 / 3 or click a card. Then press Enter to ride.':level===1?'Read the answers, then start the chase. Catch a spirit with E, or click its answer card.':'Choose an orb to walk over and collect it. Press E or the throw button to launch it.');
  text('scene-tip',level===0?'SWITCH TRACKS · ↑ / ↓ OR 1 / 2 / 3':level===1?'THE SPIRITS WAIT WHILE YOU READ':'GUARDIAN SHIELD · '+(3-round)+' / 3');
  text('status',level===0?'Which route tells the right story?':level===1?'Ready? The spirits won’t run until you start.':'Pick an answer orb. Knowledge breaks the shield.');
  $('answers').replaceChildren();current().a.forEach((answer,i)=>{let b=document.createElement('button');b.className='answer';b.setAttribute('aria-pressed','false');b.innerHTML='<span class="letter">'+String.fromCharCode(65+i)+'</span><span></span>';b.lastChild.textContent=answer;b.onclick=()=>selectAnswer(i);$('answers').append(b);});
  text('action',level===0?'Ride →':level===1?'Start chase →':'Choose an orb');$('action').disabled=level!==1;updateProgress();revealQuestion();
}
function selectAnswer(i){if(!['choose','read','chase'].includes(phase)||eliminated.has(i))return;selected=i;tone(330+i*90,.06);document.querySelectorAll('.answer').forEach((b,j)=>{b.classList.toggle('selected',j===i);b.setAttribute('aria-pressed',String(j===i));});
  if(level===0){$('action').disabled=false;text('status','Track '+String.fromCharCode(65+i)+' selected. Ready to roll?');}
  if(level===1){autoTarget=-1;text('status','Catch '+current().a[i]+'. Move with ← →, then E.');}
  if(level===2){held=-1;autoTarget=i;$('action').disabled=true;text('action','Collecting orb…');text('status','Walking to orb '+String.fromCharCode(65+i)+'.');}
}
function action(){if(level===0&&phase==='choose'&&selected>=0){ride={t:0,lane:selected};phase='ride';$('action').disabled=true;lockAnswers(true);text('status','Hold on! Following track '+String.fromCharCode(65+selected)+'…');lastRailBeat=0;sfx('rail');}
  else if(level===1&&phase==='read'){phase='chase';autoTarget=-1;$('chase-controls').hidden=false;$('stage').classList.add('is-chase');sfx('reveal');text('action','Catch nearby · E');text('scene-tip','← → MOVE · SPACE JUMP · E CATCH');text('status','');$('action').disabled=true;}
  else if(level===1&&phase==='chase'){if(catchCooldown>0)return;catchCooldown=.3;ring(player.x,player.y-25,'#fff3bf',.35);let i=targets.findIndex((p,i)=>!eliminated.has(i)&&Math.abs(p.x-player.x)<68&&Math.abs(p.y-player.y)<80);if(i>=0)resolve(i);else text('status','Move closer, then press E or Catch.');}
  else if(level===2&&phase==='choose'&&held>=0){selected=held;projectile={x:player.x+20,y:player.y-43};phase='throw';autoTarget=-1;lockAnswers(true);$('action').disabled=true;text('status','A little knowledge goes a long way…');sfx('throw');}}
function lockAnswers(lock){document.querySelectorAll('.answer').forEach((b,i)=>b.disabled=lock||eliminated.has(i));}
function settleAnswer(i){autoTarget=-1;selected=i;ride=null;projectile=null;held=-1;let correct=i===current().correct;if(correct){phase='feedback';$('chase-controls').hidden=true;$('stage').classList.remove('is-chase');if(!hadMistake)firstTry++;sfx(level===1?'catch':'correct');burst(player.x,player.y-40,levels[level].color);text('status','Correct! '+current().fact);text('action',round===2?'Collect relic ✦':'Next question →');$('action').disabled=false;lockAnswers(true);text('scene-tip',level===2?'SHIELD BROKEN · '+(round+1)+' / 3':'NICE WORK, EXPLORER!');}
  else {mistakes++;hadMistake=true;eliminated.add(i);lives=Math.max(0,lives-1);updateProgress();if(lives===0){failGame();return;}phase=level===1?'chase':'choose';selected=-1;player.x=level===0?120:player.x;camera=level===0?0:camera;document.querySelectorAll('.answer').forEach((b,j)=>{b.classList.remove('selected');b.classList.toggle('eliminated',eliminated.has(j));b.setAttribute('aria-pressed','false');});lockAnswers(false);text('status','Try again! '+current().hint);text('action',level===0?'Choose another track':level===1?'Catch nearby · E':'Choose another orb');$('action').disabled=true;tone(160,.16);}
}
function advance(){if(lives<=0)return;if(round<2){round++;setupRound();return;}relics++;updateProgress();sfx('relic');phase='between';modal('<div class="big-relic">'+levels[level].icon+'</div><h2>'+levels[level].relic+'</h2><p>'+relics+' / 3 relics found</p>',[[level<2?'Next place →':'Open treasure ✦',()=>{if(level<2){level++;round=0;introduce();}else startTreasure();},true]]);}
function finish(){if(lives<=0)return;phase='complete';updateProgress();$('action-row').hidden=false;text('status','');text('action','View reward ✦');$('action').disabled=false;lockAnswers(true);modal((goldenFlower?'<div class="secret-reward"><div class="secret-seal">✺</div><span class="tag">SECRET ARTIFACT DISCOVERED</span><h2>Heritage Legend</h2><p>The Golden Bunga Raya</p><div class="reward-code">SPECIAL PRIZE<br><small>Show this badge to your booth helper</small></div><p>3 relics · 9 questions solved · 1 secret</p></div>':'<div class="reward"><div class="big-relic">✦ ◆ ✦</div><h2>Adventure complete!</h2><p>3 relics · 9 questions solved</p><div class="reward-code">Show your booth helper<br>to claim your reward!</div></div>'),[['Next explorer ↻',startGame,true],['Close',()=>{phase='complete';}]],()=>{phase='complete';});}
$('start').onclick=startGame;$('action').onclick=()=>{if(phase==='feedback')advance();else if(phase==='complete')finish();else if(phase==='failed')startGame();else action();};
function showHelp(){modal('<h2>How to play</h2><p><strong>Tracks:</strong> correct routes move on; wrong routes trigger traps.<br><strong>Chase:</strong> pick an answer to mark its NPC, then catch it yourself. Use arrows or the on-screen buttons, then E / Catch.<br><strong>Guardian:</strong> collect an orb, then throw. Three hits defeat it.</p><p>Five lives for the whole adventure. Each wrong answer costs one. Answers shuffle for each new question.</p><p>← → move · Space jump · E catch / throw<br>1 / 2 / 3 choose · Enter confirm</p>',[['Back →',()=>{},true]]);}
function showSources(){modal('<h2>Behind the adventure</h2><p>History from your Visit Malaysia slides. The name is corrected to Sultan Abdul Samad Building. Relics and characters are fictional.</p><p><a href="https://www.malaysia.travel/explore/famous-architectural-landmarks-in-malaysia" target="_blank" rel="noopener">Tourism Malaysia: landmarks</a><br><a href="https://www.malaysia.travel/explore/kellie-s-castle" target="_blank" rel="noopener">Kellie’s Castle</a></p>',[['Back →',()=>{},true]]);}
function pauseMenu(){stopAudio();modal('<h2>Paused.</h2><div class="menu-grid"><button id="sound">Sound '+(muted?'off':'on')+'</button><button id="quality">'+(eco?'Eco · 30 fps':'Smooth · 60 fps')+'</button></div>',[['Resume →',()=>{},true],['How to play',showHelp],['Restart',()=>modal('<h2>Start again?</h2>',[['Keep playing',()=>{},true],['Restart',startGame]])],['History',showSources]]);
$('sound').onclick=()=>{muted=!muted;if(muted)stopAudio();text('sound','Sound '+(muted?'off':'on'));tone(520);};$('quality').onclick=()=>{eco=!eco;text('quality',eco?'Eco · 30 fps':'Smooth · 60 fps');};}
$('pause').onclick=pauseMenu;
$('fullscreen').onclick=async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await document.documentElement.requestFullscreen();}catch{modal('<h2>Already filling your window.</h2><p>Use your browser’s fullscreen shortcut to hide its toolbar.</p>',[['Back →',()=>{},true]]);}};
document.addEventListener('fullscreenchange',()=>{$('fullscreen').setAttribute('aria-label',document.fullscreenElement?'Exit fullscreen':'Enter fullscreen');});
window.addEventListener('keydown',e=>{if($('dialog').open)return;if(readSecretCode(e)){e.preventDefault();return;}if(e.code==='Escape'&&phase!=='home'){e.preventDefault();$('pause').click();return;}if(phase==='secret'){e.preventDefault();return;}if(['ArrowLeft','ArrowRight','ArrowUp','ArrowDown','Space'].includes(e.code)&&(e.target.tagName!=='BUTTON'||phase==='chase'))e.preventDefault();if(e.repeat&&['KeyE','Enter','Digit1','Digit2','Digit3'].includes(e.code))return;keys.add(e.code);if(['ArrowLeft','ArrowRight','KeyA','KeyD'].includes(e.code))autoTarget=-1;if(/^Digit[123]$/.test(e.code))selectAnswer(Number(e.code.slice(-1))-1);if(level===0&&phase==='choose'&&['ArrowUp','ArrowDown'].includes(e.code)){let dir=e.code==='ArrowUp'?-1:1;let i=selected;for(let j=0;j<3;j++){i=(i+dir+3)%3;if(!eliminated.has(i)){selectAnswer(i);break;}}}if(e.code==='KeyE'){e.preventDefault();action();}if(e.code==='Enter'&&(e.target.tagName!=='BUTTON'||e.target.classList.contains('answer'))){e.preventDefault();$('action').click();}});
window.addEventListener('keyup',e=>keys.delete(e.code));window.addEventListener('blur',()=>keys.clear());document.addEventListener('visibilitychange',()=>{keys.clear();last=0;if(document.hidden){stopAudio();audioContext?.suspend().catch(()=>{});}else if(!muted&&phase!=='modal')ensureAudio();});
function update(dt,elapsed=dt){if(['home','modal','complete','between','failed'].includes(phase))return;if(phase==='secret'){updateSecret(dt);return;}if(phase==='reveal'){revealElapsed+=elapsed;document.querySelector('.reveal-bar i').style.width=Math.min(100,revealElapsed/2*100)+'%';if(revealElapsed>=2)finishReveal();return;}playSeconds+=dt;catchCooldown=Math.max(0,catchCooldown-dt);updateEffects(dt);if(updateCinematic(dt))return;
  if(phase==='ride'){ride.t+=dt;player.x=120+ride.t*360;lastRailBeat+=dt;if(lastRailBeat>.14){lastRailBeat=0;sfx('rail');if(!reduced)burstSmall(player.x-20,trackY()+3,'#f5d58a',2);}if(ride.t>2.3){resolve(ride.lane);return;}}
  else if(['choose','read','chase'].includes(phase)&&level!==0){let direction=0;if(keys.has('ArrowLeft')||keys.has('KeyA'))direction--;if(keys.has('ArrowRight')||keys.has('KeyD'))direction++;if(autoTarget>=0){let target=targets[autoTarget];direction=Math.abs(target.x-player.x)>10?Math.sign(target.x-player.x):0;}
    player.vx=direction*260;player.x=Math.max(35,Math.min(1380,player.x+player.vx*dt));if(direction)player.face=direction;
    if((keys.has('Space')||keys.has('ArrowUp')||keys.has('KeyW'))&&player.y>=ground){player.vy=-370;sfx('jump');}player.vy+=1000*dt;player.y+=player.vy*dt;if(player.y>ground){player.y=ground;player.vy=0;}
    if(level===1&&phase==='chase'){targets.forEach((t,i)=>{if(eliminated.has(i))return;t.x+=t.dir*(60+i*9)*dt;if(t.x<t.base-85||t.x>t.base+85)t.dir*=-1;t.y=ground-Math.abs(Math.sin(clockTime*2+i))*12;});}
    if(level===2&&autoTarget>=0&&Math.abs(targets[autoTarget].x-player.x)<24){held=autoTarget;autoTarget=-1;text('status','Orb '+String.fromCharCode(65+held)+' collected. Throw it at the guardian!');text('action','Throw orb · E');$('action').disabled=false;sfx('insert');ring(player.x,player.y-35,'#dac7ff',.45);}
  }
  if(phase==='throw'){projectile.x+=650*dt;if(projectile.x>1260){burst(1260,ground-90,'#e0bcff');resolve(selected);}}
  let focusX=phase==='throw'&&projectile?projectile.x:level===2&&phase==='feedback'?Math.min(870,Math.max(750,player.x+290)):player.x;let desired=Math.max(0,Math.min(520,focusX-350));camera+=(desired-camera)*Math.min(1,dt*5);
}
// Compact, low-resolution pixel illustration primitives.
function rect(x,y,w,h,c){ctx.fillStyle=c;ctx.fillRect(Math.round(x),Math.round(y),w,h);}
function poly(points,c){ctx.fillStyle=c;ctx.beginPath();points.forEach(([x,y],i)=>i?ctx.lineTo(x,y):ctx.moveTo(x,y));ctx.closePath();ctx.fill();}
function circle(x,y,r,c){ctx.fillStyle=c;ctx.beginPath();ctx.arc(x,y,r,0,Math.PI*2);ctx.fill();}
function label(s,x,y,size=12,color='#fff7de',align='center'){ctx.fillStyle=color;ctx.font='bold '+size+'px Consolas, monospace';ctx.textAlign=align;ctx.fillText(s,Math.round(x),Math.round(y));}
