  if(level===0){palm(850-camera*.4,315,1.05);palm(350-camera*.3,305,.65);}else{tree(1040-camera*.45,318,1.25,level===2);tree(90-camera*.3,315,.85,level===2);}
  rect(0,316,W,11,level===2?'#79908c':'#8caf65');rect(0,327,W,10,level===2?'#5b776b':'#5b9457');rect(0,337,W,63,level===2?'#644f69':'#aa7a55');rect(0,344,W,6,level===2?'#795d78':'#c39362');for(let i=0;i<52;i++){let xx=(i*31-Math.round(camera))%1000;rect(xx,360+(i%3)*14,7+(i%4)*3,4,level===2?'#8b6a87':'#d1a274');}for(let i=0;i<34;i++){let xx=(i*53-Math.round(camera))%1100;rect(xx,310,3,8,level===2?'#a4b1a2':'#d5d894');rect(xx+4,313,3,5,level===2?'#859d93':'#cadb89');}
  if(home){explorer(575,327,1.5);for(let i=0;i<3;i++)diamond(640+i*50,286-Math.sin(clockTime*2+i)*6,'#fce39b',.7);rect(505,323,42,8,'#e5bf78');rect(514,331,25,6,'#9a744f');}
  else if(level===0){for(let lane=0;lane<3;lane++){let yy=205+lane*60;ctx.strokeStyle=selected===lane?'#f7e5a0':'#706651';ctx.lineWidth=4;ctx.beginPath();ctx.moveTo(0,308);ctx.lineTo(235-camera,308);ctx.lineTo(530-camera,yy);ctx.lineTo(1500-camera,yy);ctx.stroke();ctx.beginPath();ctx.moveTo(0,319);ctx.lineTo(235-camera,319);ctx.lineTo(530-camera,yy+11);ctx.lineTo(1500-camera,yy+11);ctx.stroke();for(let x=550;x<1500;x+=30){rect(x-camera,yy-4,7,20,selected===lane?'#c19953':'#8d7557');}answerTag(lane,655-camera,yy-32);}
    drawTrackDestination();let yy=trackY(),x=player.x-camera;ctx.save();if(cinematic?.kind==='trap'){let t=cinematic.t;ctx.translate(x,yy);if(!reduced){ctx.translate(-Math.min(t,1.5)*125,-Math.sin(Math.min(t,1.5)/1.5*Math.PI)*95);ctx.rotate(-Math.min(t,1.5)*2.4);}drawCart(0,0);ctx.restore();}else{drawCart(x,yy);ctx.restore();}}
  else{if(level===1)targets.forEach(spirit);else{targets.forEach((t,i)=>{if(eliminated.has(i)||held===i)return;let y=ground-24+(reduced?0:Math.sin(clockTime*2+i)*5);circle(t.x-camera,y,18,'#c7a6eb44');diamond(t.x-camera,y,['#ffe092','#c2ec9b','#c4b2fc'][i],1.2);answerTag(i,t.x-camera,y-35);});guardian(1280-camera,ground);if(projectile)diamond(projectile.x-camera,projectile.y,'#fff3af',1.5);}
    explorer(player.x-camera,player.y,1.1,Math.abs(player.vx)>0&&['choose','chase'].includes(phase));if(held>=0)diamond(player.x-camera+player.face*23,player.y-48,'#f4dfa7',.8);
  }
  drawEffects();
