  if(cinematic?.kind==='track-win')label('NEXT STOP →',W/2,130,25,'#fff6c1');
  if(cinematic?.kind==='trap')label('TRAP! TRY ANOTHER ROUTE',W/2,120,22,'#fff1b1');
  drawSceneryAccents();
